+	entry = kcalloc(1, sizeof(*entry), GFP_ATOMIC);
+	entry->cmd = sw_nb_inetaddr_event_to_otx2_event(event, dev);
+	entry->dst = (__force u32)htonl((__force u32)ifa->ifa_address);
+	entry->dst_len = 32;
